$$
\begin{array}{r l} \int_ {a} ^ {b} F (t) \mathrm{d} t & = \int_ {a} ^ {b} f (x) \mathrm{d} x \int_ {a} ^ {b} \mathrm{e} ^ {- | t - x |} \mathrm{d} t = \int_ {a} ^ {b} f (x) (2 - \mathrm{e} ^ {a - x} - \mathrm{e} ^ {x - b}) \mathrm{d} x \\ & = 2 \int_ {a} ^ {b} f (x) \mathrm{d} x - \int_ {a} ^ {b} f (x) \mathrm{e} ^ {a - x} \mathrm{d} x - \int_ {a} ^ {b} f (x) \mathrm{e} ^ {x - b} \mathrm{d} x. \end{array}
$$

$$
\begin{array}{r l} \int_ {a} ^ {b} f (x) \mathrm{d} x & \leqslant \frac {b - a}{2} + \frac {1}{2} \int_ {a} ^ {b} f (x) \mathrm{e} ^ {- | a - x |} \mathrm{d} x + \frac {1}{2} \int_ {a} ^ {b} f (x) \mathrm{e} ^ {- | b - x |} \mathrm{d} x \\ & \leqslant \frac {b - a}{2} + \frac {1}{2} \int_ {- \infty} ^ {+ \infty} f (x) \mathrm{e} ^ {- | a - x |} \mathrm{d} x + \frac {1}{2} \int_ {- \infty} ^ {+ \infty} f (x) \mathrm{e} ^ {- | b - x |} \mathrm{d} x \leqslant \frac {b - a}{2} + 1. \end{array}
$$
